function icon(name, cls = '') { return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.sparkle}</svg>`; }
function hydrateIcons(root = document) { $$('[data-icon]', root).forEach(el => { el.innerHTML = icon(el.dataset.icon); }); }
const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const state = { bootstrap:null, overview:null, bookings:[], calls:[], settings:null, readiness:null, route:'overview', filter:'upcoming', query:'', callQuery:'', sessionId:null, messages:[], language:'en', chatBusy:false, voiceEnabled:false, rescheduleId:null, slotRequest:0, slots:[], renderVersion:0 };
const routes = { overview:'Overview', appointments:'Appointments', calls:'Call activity', studio:'Voice studio', settings:'Business settings', launch:'Go live' };
const list = (data, key) => Array.isArray(data) ? data : Array.isArray(data?.[key]) ? data[key] : [];
const tz = () => state.bootstrap?.business?.timezone || state.bootstrap?.business?.timeZone || state.bootstrap?.timezone || 'Asia/Karachi';
const business = () => state.bootstrap?.business || {};
const dateParts = (date = new Date()) => Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:tz(),year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date).map(p=>[p.type,p.value]));
const today = () => { const p=dateParts(); return `${p.year}-${p.month}-${p.day}`; };
const fmtDate = (value, options={}) => { try{return new Intl.DateTimeFormat('en-US',{timeZone:tz(),month:'short',day:'numeric',...options}).format(new Date(value));}catch{return '—';} };
const fmtTime = value => fmtDate(value,{hour:'numeric',minute:'2-digit',month:undefined,day:undefined});
const appointmentStart = b => b.startAt || b.startsAt || b.startTime;
const serviceFor = b => state.bootstrap?.services?.find(s=>s.id===b.serviceId);
const stylistFor = b => state.bootstrap?.stylists?.find(s=>s.id===b.stylistId);
const customerName = b => b.customerName || b.customer?.name || 'Guest';
const serviceName = b => b.serviceName || serviceFor(b)?.name || 'Appointment';
const stylistName = b => b.stylistName || stylistFor(b)?.name || 'Any stylist';
const initial = name => String(name||'Guest').trim().split(/\s+/).map(s=>s[0]).slice(0,2).join('').toUpperCase();
const activeBooking = b => !['cancelled','canceled','failed'].includes(String(b.status).toLowerCase());
const price = value => {if(value==null)return '—';try{return new Intl.NumberFormat('en-US',{style:'currency',currency:business().currency||'PKR',maximumFractionDigits:0}).format(Number(value));}catch{return String(value);}};
const status = value => {const text=String(value||'confirmed');return `<span class="status-pill ${escapeHtml(text.toLowerCase().replace(/[^a-z-]/g,''))}"><i></i>${escapeHtml(text.replace(/[_-]/g,' '))}</span>`;};
function notify(message, error=false) { const node=document.createElement('div');node.className=`toast${error?' error':''}`;node.innerHTML=`${icon(error?'warning':'check')}<span>${escapeHtml(message)}</span>`;$('#toasts').append(node);setTimeout(()=>node.remove(),6500); }
function getToken(){try{return sessionStorage.getItem('salonline.token')||'';}catch{return '';}}
function setToken(token){try{token?sessionStorage.setItem('salonline.token',token):sessionStorage.removeItem('salonline.token');}catch{}}
function requestKey(body){const fingerprint=JSON.stringify({operation:state.rescheduleId||'create',body});if(state.bookingRequest?.fingerprint!==fingerprint)state.bookingRequest={fingerprint,key:crypto.randomUUID()};return state.bookingRequest.key;}
function updateStylistOptions(){const select=$('#booking-stylist'),selected=select.value,serviceId=$('#booking-service').value;const available=(state.bootstrap.stylists||[]).filter(s=>!s.serviceIds||s.serviceIds.includes(serviceId));select.innerHTML='<option value="">Any available stylist</option>'+available.map(s=>`<option value="${escapeHtml(s.id)}">${escapeHtml(s.name)}</option>`).join('');if(available.some(s=>s.id===selected))select.value=selected;}
async function api(path, options={}) {
  const headers={Accept:'application/json',...(options.body?{'Content-Type':'application/json'}:{}),...options.headers};
  const token=getToken();if(token)headers.Authorization=`Bearer ${token}`;
  const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),20000);
  let response;
  try{response=await fetch(path,{...options,headers,body:options.body?JSON.stringify(options.body):undefined,signal:controller.signal});}
  catch(error){throw new Error(error.name==='AbortError'?'The server took too long to respond. Please try again.':'The backend is not connected. Start the SalonLine server and open its dashboard address.');}
  finally{clearTimeout(timeout);}
  let data;try{data=await response.json();}catch{throw new Error('The backend did not return application data. Open the dashboard through the SalonLine server.');}
  if(!response.ok){const err=new Error(data.error?.message||data.error||data.message||`Request failed (${response.status}).`);err.status=response.status;err.details=data;throw err;}
  return data;
}
function demoBanner(){return state.bootstrap?.mode==='demo'?`<div class="demo-banner">${icon('sparkle')}<span>Demo workspace · Voice Studio uses a guided demo. Confirmed appointments are saved on this server.</span><a href="#launch">Connect your business ↗</a></div>`:'';}
function pageHeader(eyebrow,title,subtitle,actions=''){return `<div class="page-header"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="page-subtitle">${subtitle}</p></div>${actions?`<div class="header-actions">${actions}</div>`:''}</div>`;}
function bookingButton(){return `<button class="button primary" data-action="new-booking"><span class="plus">+</span>New appointment</button>`;}
function dateChip(){return `<span class="date-chip">${icon('calendar')}${fmtDate(new Date(),{weekday:'short',month:'short',day:'numeric'})}</span>`;}
function empty(iconName,title,copy,action=''){return `<div class="empty-state">${icon(iconName)}<h3>${escapeHtml(title)}</h3><p>${escapeHtml(copy)}</p>${action}</div>`;}
function errorPanel(error){return `<div class="error-panel">${icon(error.status===401?'lock':'disconnect')}<h2>${error.status===401?'Your front desk is private.':'Backend not connected.'}</h2><p>${escapeHtml(error.message)}</p>${error.status===401?'<button class="button primary" data-action="login">Sign in to workspace →</button>':'<p>From the project directory, run <code>npm start</code> and open the local server address shown in your terminal.</p><button class="button primary" data-action="retry">Try again '+icon('refresh')+'</button>'}</div>`;}
function renderBookingRows(bookings, full=false){return bookings.map((b,index)=>`<tr data-booking-id="${escapeHtml(b.id)}"><td><div class="customer-cell"><span class="customer-avatar tone-${index%4}">${escapeHtml(initial(customerName(b)))}</span><span><strong>${escapeHtml(customerName(b))}</strong><small>${escapeHtml(b.phone||b.customer?.phone||'Customer')}</small></span></div></td><td>${escapeHtml(serviceName(b))}${full?`<span class="table-secondary">${serviceFor(b)?.durationMinutes||b.durationMinutes||'—'} min</span>`:''}</td><td><span class="appointment-time">${fmtTime(appointmentStart(b))}</span><span class="table-secondary">${fmtDate(appointmentStart(b))}</span></td><td class="stylist-column">${escapeHtml(stylistName(b))}</td><td>${status(b.status)}</td>${full?`<td><span class="source-icon">${icon(b.channel?.includes('whatsapp')?'message':b.channel==='dashboard'?'calendar':'phone')}${escapeHtml(b.channel||'dashboard')}</span></td><td><button class="icon-button" aria-label="View appointment for ${escapeHtml(customerName(b))}" data-view-booking="${escapeHtml(b.id)}">${icon('arrowup')}</button></td>`:''}</tr>`).join('');}
function bookingTable(bookings,full=false){return `<div class="table-wrap"><table class="appointment-table ${full?'full-table':'overview-table'}"><thead><tr><th>CUSTOMER</th><th>SERVICE</th><th>WHEN</th><th class="stylist-column">STYLIST</th><th>STATUS</th>${full?'<th>BOOKED VIA</th><th><span class="visually-hidden">Actions</span></th>':''}</tr></thead><tbody>${renderBookingRows(bookings,full)}</tbody></table></div>`;}
function relativeTime(value){if(!value)return '—';const d=(Date.now()-new Date(value).getTime())/60000;if(!Number.isFinite(d))return '—';if(d<0||d>1440)return fmtDate(value);if(d<1)return 'Just now';if(d<60)return `${Math.floor(d)}m ago`;return `${Math.floor(d/60)}h ago`;}
function callSummary(call){return call.summary||call.outcome||call.intent||'Receptionist conversation';}
function renderOverview(){
  const s=state.overview?.stats||{};const bookings=list(state.overview,'bookings').length?list(state.overview,'bookings'):state.bookings;
  const upcoming=bookings.filter(b=>activeBooking(b)&&new Date(appointmentStart(b))>=new Date()).sort((a,b)=>new Date(appointmentStart(a))-new Date(appointmentStart(b))).slice(0,4);
  const calls=list(state.overview,'calls').length?list(state.overview,'calls'):state.calls;
  const cards=[['Appointments today',s.todayBookings??bookings.filter(b=>activeBooking(b)&&dateISO(appointmentStart(b))===today()).length,'calendar','On your salon calendar'],['Upcoming bookings',s.upcomingBookings??bookings.filter(b=>activeBooking(b)&&new Date(appointmentStart(b))>new Date()).length,'people','A little care, on the way'],['Calls completed',s.completedCalls??calls.filter(c=>['completed','complete'].includes(c.status)).length,'phone',state.bootstrap.mode==='demo'?'Includes demo conversations':'Conversations completed'],['Message queue',s.pendingMessages??0,'message','Waiting to be delivered']];
  main.innerHTML=pageHeader('A GOOD DAY STARTS HERE','Your front desk, at a glance.',`A little less admin. A little more time for your clients.`,dateChip()+bookingButton())+demoBanner()+`
    <section class="hero" aria-label="Receptionist introduction"><div class="hero-copy"><div class="hero-eyebrow"><i></i> YOUR RECEPTIONIST, ALWAYS READY</div><h2>Every call deserves<br>a <em>warm welcome.</em></h2><p>From the first hello to the next appointment, SalonLine helps your clients feel looked after.</p><div class="hero-actions"><a href="#studio" class="button peach">${icon('wave')}Try your receptionist ${icon('arrowup')}</a><a href="#launch" class="hero-secondary">View setup ${icon('arrow')}</a></div></div><div class="hero-art" aria-hidden="true"><div class="orbit one"></div><div class="orbit two"></div><div class="orbit three"></div><div class="voice-orb"><span></span><span></span><span></span><span></span><span></span><span></span><span></span></div><div class="orb-tag first">${icon('phone')}A familiar voice. A fresh start.</div><div class="orb-tag second">${icon('check')}An appointment, taken care of.</div></div><span class="hero-corner">A LITTLE MORE HUMAN.</span></section>
    <section class="stats-grid" aria-label="Workspace statistics">${cards.map(([label,value,ico,foot])=>`<article class="stat-card"><div class="stat-head">${label}${icon(ico)}</div><div class="stat-value">${escapeHtml(value)}</div><p class="stat-foot">${icon('clock')}${foot}</p></article>`).join('')}</section>
    <div class="content-grid"><section class="card"><div class="card-header"><div><h3>Coming up <span class="count-pill">${upcoming.length}</span></h3><p>Your next appointments, all in one place.</p></div><a class="text-link" href="#appointments">View all ${icon('arrow')}</a></div>${upcoming.length?bookingTable(upcoming):empty('calendar','A little breathing room.','Your next appointments will appear here.',`<button class="button secondary small" data-action="new-booking">Add an appointment</button>`)}<div class="card-foot">${icon('shield')}Availability checked before every booking</div></section>
    <section class="card"><div class="card-header"><div><h3>Around the front desk</h3><p>The latest from your receptionist.</p></div><a class="text-link" href="#calls">View all ${icon('arrow')}</a></div>${calls.length?`<div class="activity-list">${calls.slice(0,4).map((call,i)=>`<div class="activity-item"><span class="activity-icon">${icon(call.channel?.includes('whatsapp')?'message':'phone')}</span><div class="activity-text"><strong>${escapeHtml(call.customerName||call.callerName||call.fromNumber||call.from||'Incoming conversation')}</strong><p>${escapeHtml(callSummary(call))}</p></div><span class="activity-time">${relativeTime(call.startedAt||call.createdAt)}</span></div>`).join('')}</div>`:empty('phone','Your first hello awaits.','Completed conversations will appear here.')}<div class="card-foot">${icon('lock')}Customer details stay in your workspace</div></section></div><p class="bottom-note">${icon('sparkle')}More time for your craft. We’ll take care of the hello.</p>`;
}
function dateISO(value){try{const p=dateParts(new Date(value));return `${p.year}-${p.month}-${p.day}`;}catch{return '';}}
function filteredBookings(){const now=new Date();return state.bookings.filter(b=>{const active=activeBooking(b);const future=new Date(appointmentStart(b))>=now;const matches=state.filter==='all'||(state.filter==='upcoming'&&active&&future)||(state.filter==='past'&&active&&!future)||(state.filter==='cancelled'&&!active);return matches&&`${customerName(b)} ${b.phone||''} ${serviceName(b)} ${stylistName(b)}`.toLowerCase().includes(state.query.toLowerCase());}).sort((a,b)=>state.filter==='past'?new Date(appointmentStart(b))-new Date(appointmentStart(a)):new Date(appointmentStart(a))-new Date(appointmentStart(b)));}
function renderAppointments(){main.innerHTML=pageHeader('A PLACE FOR EVERY APPOINTMENT','The calendar, taken care of.','Every service, stylist and client. Beautifully in sync.',bookingButton())+demoBanner()+`<div class="toolbar"><div class="tabs" aria-label="Filter appointments">${[['upcoming','Upcoming'],['past','Past'],['cancelled','Cancelled'],['all','All appointments']].map(([id,label])=>`<button class="tab ${state.filter===id?'active':''}" data-filter="${id}" aria-pressed="${state.filter===id}">${label}</button>`).join('')}</div><label class="search-field">${icon('search')}<span class="visually-hidden">Search appointments</span><input id="booking-search" type="search" placeholder="Find a client or service…" value="${escapeHtml(state.query)}"></label></div><section class="card" id="appointment-results"></section>`;renderAppointmentResults();}
function renderAppointmentResults(){const rows=filteredBookings();$('#appointment-results').innerHTML=rows.length?bookingTable(rows,true)+`<div class="card-foot">${rows.length} appointment${rows.length!==1?'s':''} · Times shown in ${escapeHtml(tz())}</div>`:empty('calendar',state.query?'No appointments found.':'Your calendar has a little room.','Create an appointment or try another filter.',`<button class="button secondary small" data-action="new-booking">${icon('calendar')}New appointment</button>`);}
function renderCalls(){main.innerHTML=pageHeader('EVERY HELLO HAS A STORY','A closer look at every call.','Conversation summaries, outcomes and moments that need your care.',`<button class="button secondary" data-action="refresh">${icon('refresh')}Refresh</button>`)+demoBanner()+`<div class="toolbar"><span class="record-count">${state.calls.length} conversation${state.calls.length!==1?'s':''} in your workspace</span><label class="search-field">${icon('search')}<span class="visually-hidden">Search calls</span><input id="call-search" type="search" placeholder="Find a caller or outcome…" value="${escapeHtml(state.callQuery)}"></label></div><section class="card" id="call-results"></section>`;renderCallResults();}
function renderCallResults(){const calls=state.calls.map((call,index)=>({...call,_index:index})).filter(c=>`${c.fromNumber||c.from||''} ${c.customerName||''} ${callSummary(c)}`.toLowerCase().includes(state.callQuery.toLowerCase()));$('#call-results').innerHTML=calls.length?`<div class="table-wrap"><table class="appointment-table full-table"><thead><tr><th>CALLER</th><th>CONVERSATION</th><th>WHEN</th><th>DURATION</th><th>STATUS</th><th>CHANNEL</th><th></th></tr></thead><tbody>${calls.map((c,i)=>`<tr data-call-index="${c._index}"><td><div class="customer-cell"><span class="customer-avatar tone-${i%4}">${icon('phone')}</span><span><strong>${escapeHtml(c.customerName||c.callerName||'Incoming caller')}</strong><small>${escapeHtml(c.fromNumber||c.from||c.phone||'Number unavailable')}</small></span></div></td><td><div class="call-subtitle">${escapeHtml(callSummary(c))}</div></td><td>${fmtDate(c.startedAt||c.createdAt)}<span class="table-secondary">${fmtTime(c.startedAt||c.createdAt)}</span></td><td>${formatDuration(c.durationSeconds??c.duration)}</td><td>${status(c.status||'completed')}</td><td><span class="source-icon">${icon(c.channel?.includes('whatsapp')?'message':'phone')}${escapeHtml(c.channel||'phone')}</span></td><td><button class="icon-button" aria-label="View call details">${icon('arrowup')}</button></td></tr>`).join('')}</tbody></table></div><div class="card-foot">${icon('lock')}Recordings and transcripts depend on your configured retention policy.</div>`:empty('phone','Every conversation starts somewhere.','Call activity appears here after your receptionist handles a call.',`<a class="button secondary small" href="#studio">Try the receptionist ${icon('arrow')}</a>`);}
function formatDuration(value){if(value==null)return '—';const n=Number(value);if(!Number.isFinite(n))return escapeHtml(value);return `${Math.floor(n/60)}:${String(Math.floor(n%60)).padStart(2,'0')}`;}
function renderStudio(){
  if(!state.messages.length)state.messages=[{role:'assistant',content:state.language==='ur'?'السلام علیکم! SalonLine میں خوش آمدید۔ میں آپ کی اپائنٹمنٹ بک کرنے، دستیابی معلوم کرنے، یا ہماری سروسز کے بارے میں مدد کر سکتی ہوں۔ آپ کیا کروانا چاہیں گے؟':`Hello, and welcome to ${business().name||'the salon'}! I’m your SalonLine receptionist. I can help you explore our services and book an appointment. What can I do for you today?`}];
  main.innerHTML=pageHeader('A FRIENDLY VOICE. YOUR BUSINESS.','Meet your new receptionist.','Give the conversation a try before your first real call.',`<select id="studio-language" aria-label="Receptionist language"><option value="en" ${state.language==='en'?'selected':''}>English</option><option value="ur" ${state.language==='ur'?'selected':''}>اردو · Urdu</option></select>`)+demoBanner()+`<div class="studio-grid"><section class="studio-intro"><p class="eyebrow">SAY HELLO TO SALONLINE</p><h2>A thoughtful welcome.<br>Every single time.</h2><p>Your services. Your calendar. Your way of looking after people.</p><div class="studio-orb" aria-hidden="true"><div class="orbit one"></div><div class="orbit two"></div><div class="voice-orb"><span></span><span></span><span></span><span></span><span></span><span></span><span></span></div></div><ul class="studio-capabilities"><li>${icon('check')}Answers from your approved service list</li><li>${icon('check')}Checks real appointment availability</li><li>${icon('check')}Confirms details before making a booking</li><li>${icon('check')}Welcomes customers in Urdu & English</li></ul><p class="studio-disclaimer">This is the guided browser demo. Confirmed bookings are saved to this server. Browser speech uses your device’s supported voices; live phone calls use the configured voice provider.</p></section><section class="card chat-card" aria-label="Receptionist demo"><div class="chat-header"><span class="assistant-avatar">${icon('wave')}</span><div><strong>Your SalonLine receptionist</strong><p>Guided demo · Real booking calendar</p></div><button class="button secondary small" data-action="reset-chat">${icon('refresh')}Start fresh</button></div><div class="chat-messages" id="chat-messages" role="log" aria-label="Receptionist conversation" aria-live="polite"></div><div class="chat-suggestions" id="chat-suggestions">${(state.language==='ur'?['بال کٹوانے کی بکنگ کریں','آپ کی سروسز کیا ہیں؟']:['I’d like a haircut','What services do you offer?']).map(text=>`<button class="suggestion" data-prompt="${escapeHtml(text)}">${escapeHtml(text)}</button>`).join('')}</div><form class="chat-form" id="chat-form"><button class="icon-button" id="speech-toggle" type="button" aria-label="${state.voiceEnabled?'Turn off spoken responses':'Turn on spoken responses'}" title="Browser spoken responses" aria-pressed="${state.voiceEnabled}">${icon('volume')}</button><label class="visually-hidden" for="chat-input">Message the receptionist</label><input id="chat-input" name="message" required maxlength="1000" autocomplete="off" placeholder="${state.language==='ur'?'اپنا پیغام لکھیں…':'Say hello, ask a question, or book a visit…'}" ${state.language==='ur'?'dir="auto"':''}><button class="icon-button" id="speech-button" type="button" aria-label="Use browser speech recognition" title="Browser speech recognition">${icon('mic')}</button><button class="button primary" type="submit" aria-label="Send message" id="chat-send">${icon('send')}</button></form><div class="chat-footer">${icon('shield')}A booking is made only after you confirm. Browser demo.</div></section></div>`;renderMessages();const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SpeechRecognition)$('#speech-button').hidden=true;if(!window.speechSynthesis)$('#speech-toggle').hidden=true;
}
function renderMessages(){const container=$('#chat-messages');if(!container)return;container.innerHTML=state.messages.map(m=>`<div class="message ${m.role}"><div class="message-label">${m.role==='user'?'YOU':'SALONLINE'} ${m.error?'· PLEASE TRY AGAIN':''}</div><div class="message-content" dir="auto">${escapeHtml(m.content)}</div></div>`).join('')+(state.chatBusy?'<div class="message"><div class="message-label">SALONLINE</div><div class="message-content"><span class="typing"><i></i><i></i><i></i></span></div></div>':'');container.scrollTop=container.scrollHeight;$('#studio-language').disabled=state.chatBusy;$('#chat-send').disabled=state.chatBusy;$('#chat-input').disabled=state.chatBusy;$('#chat-suggestions').hidden=state.messages.length>1;}
async function sendChat(message){if(state.chatBusy||!message.trim())return;state.messages.push({role:'user',content:message.trim()});state.chatBusy=true;renderMessages();try{const data=await api('/api/demo/turn',{method:'POST',body:{sessionId:state.sessionId||undefined,message:message.trim(),language:state.language}});state.sessionId=data.sessionId||state.sessionId;state.messages.push({role:'assistant',content:data.reply||'Please try that again.'});if(state.voiceEnabled)speak(data.reply);if(data.booking){notify('Appointment confirmed and saved to your calendar.');await refreshData(false).catch(()=>{});}}catch(error){state.messages.push({role:'assistant',content:error.message,error:true});}finally{state.chatBusy=false;renderMessages();$('#chat-input')?.focus();}}
function speak(text){if(!window.speechSynthesis)return;speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang=state.language==='ur'?'ur-PK':'en-US';const voice=speechSynthesis.getVoices().find(v=>v.lang.startsWith(state.language==='ur'?'ur':'en'));if(voice)utterance.voice=voice;utterance.rate=.95;speechSynthesis.speak(utterance);}
let recognition;
function startRecognition(){const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition)return;try{recognition=new Recognition();recognition.lang=state.language==='ur'?'ur-PK':'en-US';recognition.interimResults=false;recognition.continuous=false;const btn=$('#speech-button');btn.classList.add('listening');btn.setAttribute('aria-label','Listening with browser speech recognition');recognition.onresult=e=>{const text=e.results[0][0].transcript;$('#chat-input').value=text;$('#chat-input').focus();};recognition.onerror=e=>notify(e.error==='not-allowed'?'Microphone access was not allowed. You can type your message below.':'Browser speech recognition could not complete. Please try again or type your message.',true);recognition.onend=()=>{btn.classList.remove('listening');btn.setAttribute('aria-label','Use browser speech recognition');};recognition.start();}catch{notify('Your browser could not start speech recognition. Please type your message.',true);}}
function businessHoursText(hours){if(!hours)return '';if(typeof hours==='string')return hours;const weekdays=['','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];return Object.entries(hours).map(([day,value])=>`${weekdays[Number(day)]||day}: ${value===null||value===false?'Closed':Array.isArray(value)?value.map(v=>typeof v==='string'?v:`${v.start||v.open||''}–${v.end||v.close||''}`).join(', '):typeof value==='object'?`${value.open||value.start||''}–${value.close||value.end||''}`:value}`).join('\n');}
function serviceEditor(service){return `<fieldset class="catalog-editor" data-service-row data-id="${escapeHtml(service.id)}"><legend>Service</legend><div class="editor-topline"><span>Service details</span><button class="button ghost small" type="button" data-remove-service aria-label="Remove ${escapeHtml(service.name||'this service')}">${icon('close')}Remove</button></div><div class="form-grid"><label class="span-2">Service name<input data-service-field="name" required maxlength="120" value="${escapeHtml(service.name)}"></label><label>Duration (minutes)<input data-service-field="durationMinutes" type="number" required min="5" max="480" step="1" value="${service.durationMinutes??45}"></label><label>Price <span class="editor-currency">(workspace currency)</span><input data-service-field="price" type="number" required min="0" max="100000" step="0.01" value="${service.price??0}"></label><label class="span-2">Service description<textarea data-service-field="description" maxlength="1000" rows="2" placeholder="What’s included, and anything the customer should know">${escapeHtml(service.description||'')}</textarea></label></div></fieldset>`;}
function serviceRows(){return $$('[data-service-row]').map(row=>({id:row.dataset.id,name:$('[data-service-field="name"]',row).value.trim(),durationMinutes:Number($('[data-service-field="durationMinutes"]',row).value),price:Number($('[data-service-field="price"]',row).value),description:$('[data-service-field="description"]',row).value.trim()}));}
function capabilityEditor(services,selected=[]){return services.map(service=>`<label class="capability-option"><input type="checkbox" data-service-assignment value="${escapeHtml(service.id)}" ${selected.includes(service.id)?'checked':''}><span>${escapeHtml(service.name||'Untitled service')}</span></label>`).join('');}
function stylistEditor(stylist,services){return `<fieldset class="catalog-editor" data-stylist-row data-id="${escapeHtml(stylist.id)}"><legend>Team member</legend><div class="editor-topline"><span>Team member details</span><button class="button ghost small" type="button" data-remove-stylist aria-label="Remove ${escapeHtml(stylist.name||'this team member')}">${icon('close')}Remove</button></div><label>Stylist name<input data-stylist-name required maxlength="120" value="${escapeHtml(stylist.name)}"></label><fieldset class="capabilities-fieldset"><legend>Services this stylist offers</legend><div class="capability-options">${capabilityEditor(services,stylist.serviceIds)}</div></fieldset></fieldset>`;}
function refreshCapabilities(){const services=serviceRows();$$('[data-stylist-row]').forEach(row=>{const selected=$$('[data-service-assignment]:checked',row).map(input=>input.value);$('.capability-options',row).innerHTML=capabilityEditor(services,selected);});}
function renderSettings(){
  const settings=state.settings||{},salon=settings.salon||settings.business||business(),services=settings.services||state.bootstrap.services||[],stylists=settings.stylists||state.bootstrap.stylists||[];
  const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
  main.innerHTML=pageHeader('THE DETAILS THAT MAKE YOU, YOU','Your salon. Your way.','Keep your receptionist up to date with the little things that matter.')+`<div class="settings-layout"><section class="card"><form id="settings-form" class="settings-form">
    <div class="form-section"><h3>Your business essentials</h3><p>These details guide your receptionist and appear in confirmations.</p><div class="form-grid"><label class="span-2">Business name<input name="name" required maxlength="120" value="${escapeHtml(salon.name)}"></label><label>Business phone<input name="phone" type="tel" required value="${escapeHtml(salon.phone)}"></label><label>Time zone<input name="timeZone" required value="${escapeHtml(salon.timeZone||salon.timezone||tz())}" placeholder="Asia/Karachi"></label><label class="span-2">Address<textarea name="address" rows="2" required>${escapeHtml(salon.address)}</textarea></label><label>Currency<input name="currency" required maxlength="3" pattern="[A-Za-z]{3}" value="${escapeHtml(salon.currency||'PKR')}"></label><label>Booking window (days)<input type="number" name="bookingWindowDays" min="1" max="365" step="1" required value="${salon.bookingWindowDays??60}"></label><label>Minimum notice (minutes)<input type="number" name="minLeadMinutes" min="0" max="10080" step="1" required value="${salon.minLeadMinutes??60}"></label><label>Time slot interval (minutes)<input type="number" name="slotIntervalMinutes" min="5" max="120" step="1" required value="${salon.slotIntervalMinutes??30}"></label><label>Cancellation notice (hours)<input type="number" name="cancellationHours" min="0" max="168" step="1" required value="${salon.cancellationHours??2}"></label></div><p class="form-hint">Clients must cancel or move an appointment this many hours before its start. Administrators can help with exceptions.</p></div>
    <div class="form-section"><h3>Services your clients love</h3><p>Your receptionist quotes these prices and uses each service’s duration when checking availability.</p><div class="catalog-editors" id="service-editors">${services.map(serviceEditor).join('')}</div><button type="button" class="button secondary small add-catalog-button" data-add-service><span class="plus">+</span>Add a service</button></div>
    <div class="form-section"><h3>Your team</h3><p>Select the services each stylist can perform. A stylist needs at least one service.</p><div class="catalog-editors" id="stylist-editors">${stylists.map(stylist=>stylistEditor(stylist,services)).join('')}</div><button type="button" class="button secondary small add-catalog-button" data-add-stylist><span class="plus">+</span>Add a team member</button></div>
    <div class="form-section"><h3>Your opening hours</h3><p>All times use ${escapeHtml(salon.timeZone||salon.timezone||tz())}. Availability checks these hours, stylist services and existing bookings.</p><div class="hours-editor">${days.map((day,i)=>{const hours=salon.businessHours?.[i+1];return `<fieldset class="hours-row" data-hours-day="${i+1}"><legend class="visually-hidden">${day} opening hours</legend><label class="hours-toggle"><input type="checkbox" data-hours-open ${hours?'checked':''}><span>${day}</span></label><label class="hours-time"><span class="visually-hidden">${day} opens at</span><input type="time" data-hours-start required aria-label="${day} opens at" value="${escapeHtml(hours?.open||'09:00')}" ${hours?'':'disabled'}></label><span class="hours-until" aria-hidden="true">to</span><label class="hours-time"><span class="visually-hidden">${day} closes at</span><input type="time" data-hours-end required aria-label="${day} closes at" value="${escapeHtml(hours?.close||'18:00')}" ${hours?'':'disabled'}></label><span class="hours-status">${hours?'Open':'Closed'}</span></fieldset>`;}).join('')}</div><p class="form-hint">Turn a day off to close the salon. Opening and closing times must fall on the same day. Existing future appointments must still fit the new hours.</p></div>
    <p class="form-error" id="settings-error" role="alert" tabindex="-1"></p><div class="settings-footer"><p id="settings-save-status">Save to apply your business, catalog and hours together.</p><button type="submit" class="button primary" id="save-settings">Save changes ${icon('check')}</button></div></form></section><aside class="aside-card">${icon('sparkle')}<h3>A good receptionist<br>knows your salon.</h3><p>Accurate details make every conversation feel effortless. Your agent answers from this approved information and checks the calendar before offering a time.</p><p>Services and stylists already used by future appointments stay protected. You’ll see a clear message if a change would affect a booking.</p><p>Credentials belong in your server environment. Keep passwords and API keys out of these business details.</p><a class="button secondary small" href="#studio">Hear it for yourself ${icon('arrow')}</a></aside></div>`;
}
function renderLaunch(){const readiness=state.readiness||{};const checks=readiness.checks||[];const passed=checks.filter(c=>c.ready||c.ok||c.status==='ready').length;const percent=checks.length?Math.round(passed/checks.length*100):0;main.innerHTML=pageHeader('YOUR NEXT CHAPTER STARTS HERE','Let’s open the line.','A clear path from your first test to your first real customer.',`<button class="button secondary" data-action="refresh">${icon('refresh')}Check again</button>`)+`<section class="launch-header"><div class="readiness-ring" style="--progress:${percent}%"><span>${passed}/${checks.length}</span></div><div><h2>${readiness.ready?'Your essentials are connected.':'A few details before your first hello.'}</h2><p>${escapeHtml(readiness.note||'Connect the voice and messaging providers, configure your business information, and run a complete test call before inviting your customers.')}</p></div></section>${state.bootstrap.mode==='demo'?'<div class="attention-box">You’re currently in local demo mode. Bookings work in this workspace; receiving real phone or WhatsApp calls requires your provider accounts, a public HTTPS address, and the checks below.</div>':''}<section class="readiness-list" aria-label="Production readiness checks">${checks.map(c=>{const ready=c.ready||c.ok||c.status==='ready';return `<article class="readiness-item"><span class="check-icon ${ready?'passed':''}">${icon(ready?'check':'clock')}</span><div><h3>${escapeHtml(c.label||c.name||c.id)}</h3><p>${escapeHtml(c.detail||c.message||'')}</p></div><span class="status-pill ${ready?'confirmed':'pending'}">${ready?'Ready':'Needs setup'}</span></article>`;}).join('')||empty('settings','Readiness report unavailable.','Refresh the page to check your server configuration.')}</section><div class="technical-note"><strong>Connect the channels</strong><p>Your deployment includes provider webhook endpoints. Use your public HTTPS base URL when configuring the provider; local addresses cannot receive live calls.</p>${Object.entries(readiness.webhooks||{}).map(([key,value])=>`<p>${escapeHtml(key)}: <code>${escapeHtml(value)}</code></p>`).join('')}<p>Follow the included README and deployment guide for credentials, WhatsApp eligibility, backups, security settings, and an end-to-end test call. WhatsApp calling availability depends on your provider and business eligibility.</p></div>`;}
async function refreshData(showToast=true){const results=await Promise.allSettled([api('/api/overview'),api('/api/bookings'),api('/api/calls')]);if(results[0].status==='fulfilled')state.overview=results[0].value;if(results[1].status==='fulfilled')state.bookings=list(results[1].value,'bookings');if(results[2].status==='fulfilled')state.calls=list(results[2].value,'calls');const errors=results.filter(r=>r.status==='rejected');if(errors.length)throw errors[0].reason;const count=state.bookings.filter(b=>activeBooking(b)&&new Date(appointmentStart(b))>new Date()).length;$('#nav-booking-count').textContent=count;$('#nav-booking-count').hidden=!count;if(showToast)notify('Your workspace is up to date.');}
async function renderRoute(){const version=++state.renderVersion;state.route=routes[location.hash.slice(1)]?location.hash.slice(1):'overview';$('#current-section').textContent=routes[state.route];$$('[data-route]').forEach(el=>{el.classList.toggle('active',el.dataset.route===state.route);el.dataset.route===state.route?el.setAttribute('aria-current','page'):el.removeAttribute('aria-current');});$('#sidebar').classList.remove('open');if(!state.bootstrap){await initialize();return;}main.innerHTML='<div class="page-loading"><div class="loading-mark" aria-label="Loading workspace"></div></div>';try{if(state.route==='settings')state.settings=await api('/api/settings');else if(state.route==='launch')state.readiness=await api('/api/readiness');else if(state.route!=='studio')await refreshData(false);if(version!==state.renderVersion)return;({overview:renderOverview,appointments:renderAppointments,calls:renderCalls,studio:renderStudio,settings:renderSettings,launch:renderLaunch})[state.route]();main.focus({preventScroll:true});}catch(error){if(version!==state.renderVersion)return;main.innerHTML=errorPanel(error);if(error.status===401)showDialog('auth-dialog');}}
function showDialog(id){const dialog=$(`#${id}`);if(!dialog.open)dialog.showModal();}
async function initialize(){try{state.bootstrap=await api('/api/bootstrap');const name=business().name||'Your salon';$('#sidebar-business').textContent=name;$('#business-avatar').textContent=initial(name).slice(0,1);const demo=state.bootstrap.mode==='demo';$('#auth-button').hidden=!state.bootstrap.authRequired;$('#connection-badge').className=`connection-badge${demo?' demo':''}`;$('#connection-badge').innerHTML=`<i></i>${demo?'Demo workspace':'Connected to server'}`;$('#environment-label').textContent=demo?'Local demo environment':'Business environment';$('#business-card').title=name;$('#slot-timezone').textContent=tz();await renderRoute();}catch(error){$('#connection-badge').className='connection-badge error';$('#connection-badge').innerHTML='<i></i>Backend offline';$('#environment-label').textContent='Backend not connected';main.innerHTML=errorPanel(error);}}
async function openBooking(id){state.rescheduleId=id||null;state.bookingRequest=null;const dialog=$('#booking-dialog'),form=$('#booking-form');form.reset();$('#booking-error').textContent='';$('#booking-start').value='';$('#booking-date').min=today();$('#booking-date').value=today();const existing=id?state.bookings.find(b=>b.id===id):null;$('.modal-header h2',dialog).textContent=existing?'Move appointment':'New appointment';$('#save-booking').innerHTML=(existing?'Confirm new time':'Confirm appointment')+' '+icon('arrowup');$('#booking-service').innerHTML=(state.bootstrap.services||[]).map(s=>`<option value="${escapeHtml(s.id)}">${escapeHtml(s.name)} · ${s.durationMinutes} min · ${price(s.price)}</option>`).join('');$('#booking-stylist').innerHTML='<option value="">Any available stylist</option>'+(state.bootstrap.stylists||[]).map(s=>`<option value="${escapeHtml(s.id)}">${escapeHtml(s.name)}</option>`).join('');$$('.customer-fields input',form).forEach(input=>input.readOnly=!!existing);$('#booking-service').disabled=!!existing;if(existing){$('#booking-service').value=existing.serviceId;$('#booking-stylist').value=existing.stylistId;$('#booking-date').value=dateISO(appointmentStart(existing))<today()?today():dateISO(appointmentStart(existing));form.elements.customerName.value=customerName(existing);form.elements.phone.value=existing.phone||existing.customer?.phone||'';form.elements.whatsappConsent.checked=!!existing.whatsappConsent;}updateStylistOptions();showDialog('booking-dialog');await loadSlots();}
async function loadSlots(){const version=++state.slotRequest;$('#booking-start').value='';$('#booking-slots').innerHTML='<p class="muted">Finding a little room in the calendar…</p>';const date=$('#booking-date').value,serviceId=$('#booking-service').value,stylistId=$('#booking-stylist').value;if(!date||!serviceId)return;try{const query=new URLSearchParams({date,serviceId,...(stylistId?{stylistId}:{})});const data=await api(`/api/availability?${query}`);if(version!==state.slotRequest)return;state.slots=list(data,'slots');$('#booking-slots').innerHTML=state.slots.length?state.slots.map((slot,i)=>`<button type="button" class="slot-button" data-slot="${i}" aria-pressed="false">${escapeHtml(slot.label||fmtTime(slot.startAt))}${!stylistId&&slot.stylistName?`<small class="table-secondary">${escapeHtml(slot.stylistName)}</small>`:''}</button>`).join(''):'<p class="muted">No open times on this date. Try another day or stylist.</p>';}catch(error){if(version===state.slotRequest)$('#booking-slots').innerHTML=`<p class="form-error">${escapeHtml(error.message)}</p>`;}}
function showBookingDetail(id){const b=state.bookings.find(item=>item.id===id);if(!b)return;const active=activeBooking(b);$('#detail-content').innerHTML=`<div class="modal-header"><div><p class="eyebrow">APPOINTMENT DETAILS</p><h2>${escapeHtml(customerName(b))}</h2></div><button class="icon-button" data-close-dialog="detail-dialog" aria-label="Close appointment details">${icon('close')}</button></div><div class="modal-body"><dl class="detail-grid"><div><dt>SERVICE</dt><dd>${escapeHtml(serviceName(b))}</dd></div><div><dt>STYLIST</dt><dd>${escapeHtml(stylistName(b))}</dd></div><div><dt>DATE & TIME</dt><dd>${fmtDate(appointmentStart(b))} · ${fmtTime(appointmentStart(b))}</dd></div><div><dt>STATUS</dt><dd>${status(b.status)}</dd></div><div><dt>PHONE</dt><dd>${escapeHtml(b.phone||b.customer?.phone||'—')}</dd></div><div><dt>BOOKED VIA</dt><dd>${escapeHtml(b.channel||'dashboard')}</dd></div></dl><p class="form-hint">Times shown in ${escapeHtml(tz())}. Verify the customer’s identity before changing an appointment on their behalf.</p><div id="detail-action-message" role="alert"></div></div><div class="modal-footer">${active?`<button class="button secondary" data-cancel-booking="${escapeHtml(b.id)}">Cancel appointment</button><button class="button primary" data-reschedule-booking="${escapeHtml(b.id)}">Move appointment ${icon('arrow')}</button>`:`<button class="button secondary" data-close-dialog="detail-dialog">Close</button>`}</div>`;showDialog('detail-dialog');}
function showCallDetail(index){const call=state.calls[index];if(!call)return;const transcript=Array.isArray(call.transcript)?call.transcript.map(m=>`${m.role||m.speaker||'Speaker'}: ${m.content||m.text||''}`).join('\n\n'):call.transcript||'';$('#detail-content').innerHTML=`<div class="modal-header"><div><p class="eyebrow">A MOMENT AT THE FRONT DESK</p><h2>Conversation details</h2></div><button class="icon-button" data-close-dialog="detail-dialog" aria-label="Close call details">${icon('close')}</button></div><div class="modal-body"><dl class="detail-grid"><div><dt>CALLER</dt><dd>${escapeHtml(call.fromNumber||call.from||call.phone||'Unavailable')}</dd></div><div><dt>CHANNEL</dt><dd>${escapeHtml(call.channel||'phone')}</dd></div><div><dt>WHEN</dt><dd>${fmtDate(call.startedAt||call.createdAt)} · ${fmtTime(call.startedAt||call.createdAt)}</dd></div><div><dt>STATUS</dt><dd>${status(call.status||'completed')}</dd></div></dl><h3 class="transcript-label">SUMMARY</h3><p class="detail-transcript">${escapeHtml(callSummary(call))}</p>${transcript?`<h3 class="transcript-label">TRANSCRIPT</h3><div class="detail-transcript">${escapeHtml(transcript)}</div>`:'<p class="form-hint">No transcript retained for this conversation.</p>'}</div><div class="modal-footer"><button class="button secondary" data-close-dialog="detail-dialog">Close</button></div>`;showDialog('detail-dialog');}
document.addEventListener('click',async event=>{
  if(event.target.closest('[data-add-service]')){const service={id:`svc_${crypto.randomUUID().replaceAll('-','')}`,name:'New service',durationMinutes:45,price:0,description:''};$('#service-editors').insertAdjacentHTML('beforeend',serviceEditor(service));refreshCapabilities();$('#service-editors [data-service-row]:last-child input').focus();return;}
  if(event.target.closest('[data-remove-service]')){if($$('[data-service-row]').length<2){notify('Keep at least one service in your catalog.',true);return;}event.target.closest('[data-service-row]').remove();refreshCapabilities();return;}
  if(event.target.closest('[data-add-stylist]')){const services=serviceRows();const stylist={id:`staff_${crypto.randomUUID().replaceAll('-','')}`,name:'New team member',serviceIds:services[0]?[services[0].id]:[]};$('#stylist-editors').insertAdjacentHTML('beforeend',stylistEditor(stylist,services));$('#stylist-editors [data-stylist-row]:last-child input').focus();return;}
  if(event.target.closest('[data-remove-stylist]')){if($$('[data-stylist-row]').length<2){notify('Keep at least one team member.',true);return;}event.target.closest('[data-stylist-row]').remove();return;}
  const close=event.target.closest('[data-close-dialog]');if(close){$(`#${close.dataset.closeDialog}`).close();return;}
  const action=event.target.closest('[data-action]')?.dataset.action;
  if(action==='new-booking'){await openBooking();return;}if(action==='retry'){await initialize();return;}if(action==='login'){showDialog('auth-dialog');return;}if(action==='refresh'){await renderRoute();return;}
  if(action==='reset-chat'){if(state.chatBusy)return;if(state.sessionId){try{await api('/api/demo/end',{method:'POST',body:{sessionId:state.sessionId}});}catch{}}state.sessionId=null;state.messages=[];window.speechSynthesis?.cancel();renderStudio();return;}
  const filter=event.target.closest('[data-filter]');if(filter){state.filter=filter.dataset.filter;renderAppointments();return;}
  const slot=event.target.closest('[data-slot]');if(slot){const data=state.slots[Number(slot.dataset.slot)];$('#booking-start').value=data.startAt;$('#booking-start').dataset.stylistId=data.stylistId;$$('.slot-button').forEach(b=>{const selected=b===slot;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',selected);});return;}
  const reschedule=event.target.closest('[data-reschedule-booking]');if(reschedule){$('#detail-dialog').close();await openBooking(reschedule.dataset.rescheduleBooking);return;}
  const cancel=event.target.closest('[data-cancel-booking]');if(cancel){const message=$('#detail-action-message');if(cancel.dataset.confirmed!=='true'){message.innerHTML='<p class="form-error">Cancel this appointment? Click “Confirm cancellation” below to release this time.</p>';cancel.textContent='Confirm cancellation';cancel.className='button danger';cancel.dataset.confirmed='true';return;}cancel.disabled=true;try{await api(`/api/bookings/${encodeURIComponent(cancel.dataset.cancelBooking)}/cancel`,{method:'POST',body:{confirmed:true}});$('#detail-dialog').close();notify('Appointment cancelled. This time is available again.');await renderRoute();}catch(error){message.innerHTML=`<p class="form-error">${escapeHtml(error.message)}</p>`;cancel.disabled=false;}return;}
  const booking=event.target.closest('[data-booking-id]');if(booking){showBookingDetail(booking.dataset.bookingId);return;}
  const call=event.target.closest('[data-call-index]');if(call){showCallDetail(Number(call.dataset.callIndex));return;}
  const prompt=event.target.closest('[data-prompt]');if(prompt){await sendChat(prompt.dataset.prompt);return;}
  if(event.target.closest('#speech-button')){startRecognition();return;}
  if(event.target.closest('#speech-toggle')){state.voiceEnabled=!state.voiceEnabled;$('#speech-toggle').setAttribute('aria-pressed',state.voiceEnabled);$('#speech-toggle').style.color=state.voiceEnabled?'var(--green)':'';if(!state.voiceEnabled)window.speechSynthesis?.cancel();notify(state.voiceEnabled?'Browser spoken responses enabled. Voice availability depends on your device.':'Spoken responses turned off.');}
});
document.addEventListener('input',event=>{if(event.target.id==='booking-search'){state.query=event.target.value;renderAppointmentResults();}if(event.target.id==='call-search'){state.callQuery=event.target.value;renderCallResults();}});
document.addEventListener('change',async event=>{if(event.target.matches('[data-service-field="name"]'))refreshCapabilities();if(event.target.matches('[data-hours-open]')){const row=event.target.closest('[data-hours-day]');$$('input[type="time"]',row).forEach(input=>input.disabled=!event.target.checked);$('.hours-status',row).textContent=event.target.checked?'Open':'Closed';}if(event.target.id==='booking-service')updateStylistOptions();if(['booking-service','booking-stylist','booking-date'].includes(event.target.id))await loadSlots();if(event.target.id==='studio-language'){if(state.sessionId)await api('/api/demo/end',{method:'POST',body:{sessionId:state.sessionId}}).catch(()=>{});state.language=event.target.value;state.messages=[];state.sessionId=null;renderStudio();}});
document.addEventListener('submit',async event=>{
  if(event.target.id==='chat-form'){event.preventDefault();const input=$('#chat-input');const value=input.value;input.value='';await sendChat(value);}
  if(event.target.id==='settings-form'){event.preventDefault();const btn=$('#save-settings');btn.disabled=true;$('#settings-error').textContent='';const fields=new FormData(event.target);const salon=Object.fromEntries(fields);['bookingWindowDays','minLeadMinutes','slotIntervalMinutes','cancellationHours'].forEach(k=>salon[k]=Number(salon[k]));salon.currency=salon.currency.toUpperCase();salon.businessHours=Object.fromEntries($$('[data-hours-day]').map(row=>[row.dataset.hoursDay,$('[data-hours-open]',row).checked?{open:$('[data-hours-start]',row).value,close:$('[data-hours-end]',row).value}:null]));const services=serviceRows();const stylists=$$('[data-stylist-row]').map(row=>({id:row.dataset.id,name:$('[data-stylist-name]',row).value.trim(),serviceIds:$$('[data-service-assignment]:checked',row).map(input=>input.value)}));try{state.settings=await api('/api/settings',{method:'PUT',body:{salon,services,stylists}});state.bootstrap=await api('/api/bootstrap');$('#sidebar-business').textContent=business().name;$('#settings-save-status').textContent='Saved. Your receptionist is up to date.';$('#settings-save-status').className='settings-save-status';notify('Your business details, services and hours have been saved.');}catch(error){$('#settings-error').textContent=error.message;$('#settings-error').focus();}finally{btn.disabled=false;}}
});
$('#booking-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.target,error=$('#booking-error'),button=$('#save-booking');error.textContent='';const startAt=$('#booking-start').value;if(!startAt){error.textContent='Choose an available appointment time first.';return;}button.disabled=true;const stylistId=$('#booking-start').dataset.stylistId||$('#booking-stylist').value;const body=state.rescheduleId?{startAt,stylistId,confirmed:true}:{serviceId:$('#booking-service').value,stylistId,startAt,customerName:form.elements.customerName.value.trim(),phone:form.elements.phone.value.trim(),channel:'dashboard',whatsappConsent:form.elements.whatsappConsent.checked,confirmed:true};try{await api(state.rescheduleId?`/api/bookings/${encodeURIComponent(state.rescheduleId)}/reschedule`:'/api/bookings',{method:'POST',headers:{'Idempotency-Key':requestKey(body)},body});$('#booking-dialog').close();notify(state.rescheduleId?'Appointment moved and calendar updated.':'Appointment confirmed. A lovely visit is on the calendar.');await renderRoute();}catch(err){error.textContent=err.message;if(err.status===409)await loadSlots();}finally{button.disabled=false;}});
$('#auth-form').addEventListener('submit',async event=>{event.preventDefault();const button=$('button[type="submit"]',event.target);button.disabled=true;$('#auth-error').textContent='';try{const data=await api('/api/auth/login',{method:'POST',body:{password:$('#admin-token').value}});setToken(data.token);$('#admin-token').value='';$('#auth-dialog').close();notify('Welcome back to your workspace.');await renderRoute();}catch(error){$('#auth-error').textContent=error.message;}finally{button.disabled=false;}});
$('#signout-button').addEventListener('click',()=>{setToken('');$('#auth-dialog').close();notify('Your browser access session has been cleared.');renderRoute();});
